<?php
/** School Intelligence 5.0.0: explicit capabilities and additive configuration. */
if(!defined('SCHOOLOS_INSIGHTS_LIBRARY')){header('Location: index.php?s=intelligence');exit;}
function ix_schema():array{return [
 "CREATE TABLE IF NOT EXISTS ix_roles(tenant_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,capability VARCHAR(40) NOT NULL,PRIMARY KEY(tenant_id,user_id,capability)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
 "CREATE TABLE IF NOT EXISTS ix_settings(tenant_id BIGINT UNSIGNED PRIMARY KEY,copilot_enabled TINYINT NOT NULL DEFAULT 0,offline_enabled TINYINT NOT NULL DEFAULT 0,wallet_enabled TINYINT NOT NULL DEFAULT 0,pickup_required TINYINT NOT NULL DEFAULT 0,export_days INT NOT NULL DEFAULT 7,review_note VARCHAR(1000) NOT NULL,updated_by BIGINT UNSIGNED NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4"
];}
function ix_caps():array{return ['reports_view','finance_reports','hr_reports','success_reviewer','pickup_officer','flow_approver','curriculum_manager','timetable_manager','wallet_cashier','alumni_manager','accreditation_manager','privacy_officer','group_analyst','integration_manager'];}
function ix_tables():array{return ['ix_roles','ix_settings','rp_definitions','rp_schedules','rp_exports','rp_cohorts','rp_members','ix_alerts','ix_drafts','ix_ai_usage','ix_pickup_tokens','ix_wa_flows','ix_wa_inbound','ix_sync','at_curricula','at_class_policies','at_designs','at_observations','at_calendars','at_rooms','at_slots','at_unavailable','at_plans','dw_accounts','dw_controls','dw_entries','dw_topups','dw_menu','gv_bank_receipts','gv_alumni','gv_mentoring','gv_funds','gv_donations','gv_scholarships','gv_applications','gv_evidence','gv_deadlines','gv_processing','gv_requests','gv_groups','gv_members','gv_group_users','gv_policies','gv_adoptions','gv_plugins','gv_api_tokens','gv_api_usage'];}
function ix_ready(bool $refresh=false):bool{static $cached=null;if($refresh)$cached=null;if($cached!==null)return $cached;foreach(ix_tables() as $t)if(!op_has($t))return $cached=false;return $cached=true;}
function ix_install():void{global $pdo;sv_install();foreach(array_merge(ix_schema(),rp_schema(),si_schema(),at_schema(),dw_schema(),gv_schema()) as $sql)$pdo->exec($sql);ix_ready(true);}
function ix_can(array $u,string $cap):bool{return $u['role']==='school_admin'||(in_array($u['role'],['staff','teacher'],true)&&(bool)g('SELECT user_id FROM ix_roles WHERE tenant_id=? AND user_id=? AND capability=?',[$u['tenant_id'],$u['id'],$cap]));}
function ix_need(array $u,string $cap):void{if(!ix_can($u,$cap))throw new RuntimeException('Requires '.$cap.' access.');}
function ix_own(string $table,array $u,int $id,bool $lock=false):array{if(!in_array($table,array_merge(ix_tables(),['subjects','ac_allocations','ac_assessments']),true))return sv_own($table,$u,$id,$lock);$r=q("SELECT * FROM `$table` WHERE tenant_id=? AND id=?".($lock?' FOR UPDATE':''),[$u['tenant_id'],$id])->fetch();if(!$r)throw new RuntimeException('Record unavailable.');return $r;}
function ix_setting(int $tid,string $key):int{if(!in_array($key,['copilot_enabled','offline_enabled','wallet_enabled','pickup_required','export_days'],true))throw new LogicException('Invalid setting.');if(!op_has('ix_settings'))return $key==='export_days'?7:0;$value=(int)g("SELECT `$key` FROM ix_settings WHERE tenant_id=?",[$tid]);return $key==='export_days'?($value?:7):$value;}
function ix_key(string $v,int $max=100):string{if(strlen($v)>$max||!preg_match('/^[A-Za-z0-9_-]+$/D',$v))throw new RuntimeException('Use a reference containing letters, digits, underscores or hyphens.');return $v;}
function ix_fresh(int $tid,int $uid):array{$u=q('SELECT * FROM users WHERE tenant_id=? AND id=? AND active=1',[$tid,$uid])->fetch();if(!$u||!in_array($u['role'],['school_admin','staff','teacher','parent','student'],true))throw new RuntimeException('Account is no longer authorized.');return $u;}
function ix_form(string $action,array $fields,string $button):void{echo '<form method="post" enctype="multipart/form-data" class="op-form"><input type="hidden" name="csrf" value="'.e($_SESSION['csrf']).'"><input type="hidden" name="ix_action" value="'.e($action).'">';foreach($fields as $key=>$spec){[$label,$type]=$spec;if(is_array($type))op_select($key,$label,$type);elseif($type==='check')echo '<label class="op-check"><input type="checkbox" name="'.e($key).'" value="yes"'.(!empty($spec[2])?' checked':'').'>'.e($label).'</label>';else op_field($key,$label,$type,(string)($spec[2]??''),(bool)($spec[3]??true));}op_end($button);}
function ix_tabs(string $area,array $tabs,string $default):string{$v=is_string($_GET['view']??null)?$_GET['view']:$default;if(!isset($tabs[$v]))$v=$default;echo '<nav class="ix-nav">';foreach($tabs as $k=>$name)echo '<a '.($v===$k?'aria-current="page"':'').' href="?s=intelligence&amp;area='.$area.'&amp;view='.e($k).'">'.e($name).'</a>';echo '</nav>';return $v;}
function ix_action(array $u):string{if(!hash_equals((string)($_SESSION['csrf']??''),(string)($_POST['csrf']??'')))throw new RuntimeException('Security token expired.');$a=op_text('ix_action',50,true);if($a==='activate'){if($u['role']!=='school_admin')throw new RuntimeException('School administrator required.');ix_install();return 'School Intelligence activated; existing records retained.';}if(!ix_ready())throw new RuntimeException('Activate School Intelligence first.');if($a==='grant'){if($u['role']!=='school_admin')throw new RuntimeException('School administrator required.');$t=sv_own('users',$u,op_id('user_id'));if(!$t['active']||!in_array($t['role'],['staff','teacher'],true))throw new RuntimeException('Choose an active employee account.');$cap=sv_enum('capability',ix_caps());if(sv_enum('decision',['grant','revoke'])==='grant')q('INSERT IGNORE INTO ix_roles VALUES(?,?,?)',[$u['tenant_id'],$t['id'],$cap]);else q('DELETE FROM ix_roles WHERE tenant_id=? AND user_id=? AND capability=?',[$u['tenant_id'],$t['id'],$cap]);audit('intelligence.access','user',$t['id'].' '.$cap);return 'Intelligence capability updated.';}
 if($a==='settings'){if($u['role']!=='school_admin'||op_text('reviewed',10)!=='yes')throw new RuntimeException('School administrator must confirm operational, privacy and provider review.');$days=sv_qty('export_days',30);$credential=op_text('copilot_api_key',4000);if($credential!==''&&preg_match('/[\x00-\x20]/',$credential))throw new RuntimeException('Invalid provider credential.');q('INSERT INTO ix_settings(tenant_id,copilot_enabled,offline_enabled,wallet_enabled,pickup_required,export_days,review_note,updated_by) VALUES(?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE copilot_enabled=VALUES(copilot_enabled),offline_enabled=VALUES(offline_enabled),wallet_enabled=VALUES(wallet_enabled),pickup_required=VALUES(pickup_required),export_days=VALUES(export_days),review_note=VALUES(review_note),updated_by=VALUES(updated_by)',[$u['tenant_id'],isset($_POST['copilot_enabled'])?1:0,isset($_POST['offline_enabled'])?1:0,isset($_POST['wallet_enabled'])?1:0,isset($_POST['pickup_required'])?1:0,$days,op_text('review_note',1000,true),$u['id']]);$key=op_text('copilot_api_key',4000);if($key!==''){if(preg_match('/[\x00-\x20]/',$key))throw new RuntimeException('Invalid provider credential.');sv_save_secret((int)$u['tenant_id'],'copilot_api_key',$key);}audit('intelligence.settings','tenant',(string)$u['tenant_id']);return 'Reviewed school settings saved. No background sending, spending or AI action was initiated.';}
 foreach(['rp_'=>'rp_action','si_'=>'si_action','at_'=>'at_action','dw_'=>'dw_action','gv_'=>'gv_action'] as $prefix=>$function)if(str_starts_with($a,$prefix))return $function($u,substr($a,strlen($prefix)));throw new RuntimeException('Unsupported intelligence action.');}
function ix_render(array $u):void{
 echo '<style>.ix-hero{padding:28px;background:linear-gradient(115deg,#17234d,#126d79);color:white;border-radius:20px}.ix-nav{display:flex;gap:8px;flex-wrap:wrap;margin:20px 0}.ix-nav a{padding:11px;border:1px solid var(--line);border-radius:10px;background:var(--card-bg);color:var(--ink);text-decoration:none}.op-card{background:var(--card-bg);padding:24px;border:1px solid var(--line);border-radius:16px;margin:18px 0}.op-scroll{overflow:auto}.op-form{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px;margin:18px 0}.op-form label{display:grid;gap:6px}.op-form input,.op-form select,.op-form textarea{padding:11px;border:1px solid var(--line);border-radius:8px;background:var(--field-bg);color:var(--field-text);font:inherit;width:100%}.op-form label:has(textarea){grid-column:1/-1}.op-form .op-check{display:flex;align-items:center}.op-check input{width:auto}.ix-kpis{display:flex;gap:15px;flex-wrap:wrap}.ix-kpis div{border:1px solid var(--line);padding:20px;border-radius:12px}.ix-kpis strong{font-size:25px;display:block}.op-card p{overflow-wrap:anywhere}pre{white-space:pre-wrap;overflow-wrap:anywhere}@media(max-width:650px){.op-form{grid-template-columns:1fr}.op-card{padding:15px}}</style><div class="ix-hero"><h2>School Intelligence</h2><p>Evidence, decisions and school improvement—with human review.</p></div>';
 if(!ix_ready()){op_card('Activate School Intelligence');echo '<p>Back up the database. Activation adds intelligence tables; AI, offline capture, prepaid credits and mandatory pickup tokens remain disabled until explicitly reviewed and enabled.</p>';if($u['role']==='school_admin')ix_form('activate',[],'Activate School Intelligence');else echo '<p>Ask the school administrator to activate this release.</p>';echo '</section>';return;}
 $area=is_string($_GET['area']??null)?$_GET['area']:px_default_insight($u);echo '<nav class="ix-nav">';foreach(['reports'=>'Reporting & Analytics','innovations'=>'Copilot, Success & Pickup','academics'=>'Curriculum, Reports & Timetable','wallet'=>'School prepaid credits','governance'=>'Alumni, Accreditation & HQ','settings'=>'Access & settings'] as $k=>$v){if(!px_insight_area($u,$k))continue;if($k==='settings'&&$u['role']!=='school_admin')continue;echo '<a href="?s=intelligence&amp;area='.$k.'">'.e($v).'</a>';}echo '</nav>';
 if($area==='innovations')si_render($u);elseif($area==='academics')at_render($u);elseif($area==='wallet')dw_render($u);elseif($area==='governance')gv_render($u);elseif($area==='settings'){
  if($u['role']!=='school_admin')throw new RuntimeException('School administrator required.');op_card('Scoped access');ix_form('grant',['user_id'=>['Active staff/teacher',op_choices(q("SELECT id,name FROM users WHERE tenant_id=? AND active=1 AND role IN ('staff','teacher')",[$u['tenant_id']])->fetchAll())],'capability'=>['Capability',array_combine(ix_caps(),ix_caps())],'decision'=>['Decision',['grant'=>'Grant','revoke'=>'Revoke']]],'Save access');op_table(q('SELECT u.name,r.capability FROM ix_roles r JOIN users u ON u.id=r.user_id AND u.tenant_id=r.tenant_id WHERE r.tenant_id=?',[$u['tenant_id']])->fetchAll(),['Account','Capability']);echo '</section>';op_card('Reviewed school controls');ix_form('settings',['copilot_enabled'=>['Enable optional external AI summaries of authorized aggregates','check',ix_setting((int)$u['tenant_id'],'copilot_enabled')],'offline_enabled'=>['Enable encrypted selective teacher offline capture','check',ix_setting((int)$u['tenant_id'],'offline_enabled')],'wallet_enabled'=>['Enable purpose-limited school prepaid credits after accounting/provider/legal review','check',ix_setting((int)$u['tenant_id'],'wallet_enabled')],'pickup_required'=>['Require short-lived token for transport guardian handovers','check',ix_setting((int)$u['tenant_id'],'pickup_required')],'export_days'=>['Private export retention days (1–30)','number','7'],'copilot_api_key'=>['Optional school AI provider key (blank keeps existing)','password','',false],'review_note'=>['Operational, data protection and provider review record','textarea'],'reviewed'=>['I confirm the school has reviewed these controls and required arrangements','check']],'Save reviewed controls');op_table(q('SELECT copilot_enabled,offline_enabled,wallet_enabled,pickup_required,export_days,review_note FROM ix_settings WHERE tenant_id=?',[$u['tenant_id']])->fetchAll(),['AI','Offline','Wallet','Pickup tokens','Export days','Review record']);echo '</section>';
 }else rp_render($u);
}
